const __pageData = JSON.parse('{"title":"DOGE (Department of Government Efficiency)","description":"","frontmatter":{"title":"DOGE (Department of Government Efficiency)","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["government","efficiency","trump-administration"],"sources":["raw/a-journey-of-ever-changing-truths.md","raw/badlands-brief-70c.md","raw/badlands-brief-861.md","raw/badlands-brief-b24.md","raw/badlands-brief-a1a.md","raw/badlands-brief-c07.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-08e.md","raw/badlands-news-brief-155.md","raw/badlands-news-brief-1c8.md","raw/badlands-news-brief-1f2.md","raw/badlands-news-brief-24e.md","raw/badlands-news-brief-324.md","raw/badlands-news-brief-32c.md","raw/badlands-news-brief-3a5.md","raw/badlands-news-brief-426.md","raw/badlands-news-brief-457.md","raw/badlands-news-brief-4a9.md","raw/badlands-news-brief-508.md","raw/badlands-news-brief-52f.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-71f.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-795.md","raw/badlands-news-brief-7b8.md","raw/badlands-news-brief-7ce.md","raw/badlands-news-brief-7e5.md","raw/badlands-news-brief-8dc.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/doge.md","filePath":"entities/doge.md","lastUpdated":null}');
